INSERT INTO public.products (code, name, category, variant, description, pattern, option_label, options, min_qty, price_ngn, price_gbp, volume_tiers, stock_status, image_url, gallery, published, sort_order)
SELECT v.code, v.name, v.category, v.variant, v.description, v.pattern, v.option_label, v.options, v.min_qty, v.price_ngn, v.price_gbp, v.volume_tiers, v.stock_status, v.image_url, v.gallery, v.published, v.sort_order
FROM (VALUES
  ('ANK-001', 'Premium 100% Cotton Ankara', 'Fabrics', '3-Yard Bundle', 'Authentic, high-grade cotton weave featuring traditional vibrant print styling.', 'Heritage wax print', 'Choose a print', ARRAY['Ochre Bloom', 'Indigo Grid', 'Coral Vine']::text[], 1, 3000::numeric, 7.5::numeric, '[]'::jsonb, 'In Stock', 'asset:product-fabric.jpg', '[{"src":"asset:detail-fabric-macro.jpg","caption":"Cotton wax print detail"},{"src":"asset:detail-fabric-stack.jpg","caption":"Three-yard fabric bundle"}]'::jsonb, true, 1),
  ('RTW-002', 'Elegance Bubu Gown', 'Ready-to-Wear', 'Free Size', 'Flowing, sophisticated silhouette engineered for modern everyday luxury.', 'Sculptural floral', 'Select a print', ARRAY['Ochre Bloom', 'Coral Vine']::text[], 1, 12500::numeric, 32::numeric, '[]'::jsonb, 'Limited Stock', 'asset:product-bubu.jpg', '[{"src":"asset:detail-bubu-macro.jpg","caption":"Print and finish detail"},{"src":"asset:detail-bubu-full.jpg","caption":"Full bubu silhouette"}]'::jsonb, true, 2),
  ('RTW-003', 'Tailored Palazzo Trousers', 'Ready-to-Wear', 'Adjustable Waist', 'Wide-leg cut with premium pattern alignment across all structural seams.', 'Geometric wax print', 'Select a print', ARRAY['Indigo Grid', 'Ochre Bloom']::text[], 1, 8500::numeric, 22::numeric, '[]'::jsonb, 'In Stock', 'asset:product-palazzo.jpg', '[{"src":"asset:detail-palazzo-macro.jpg","caption":"Pattern alignment detail"},{"src":"asset:detail-palazzo-styled.jpg","caption":"Styled palazzo silhouette"}]'::jsonb, true, 3),
  ('ASO-004', 'Custom Asoebi Bulk Supply', 'Asoebi', 'Minimum 10 Packs', 'High-volume fabric pairing and coordination tailored for traditional event sizing.', 'Coordinated event print', 'Choose a print', ARRAY['Ochre Bloom', 'Indigo Grid', 'Coral Vine']::text[], 10, 2800::numeric, 7::numeric, '[{"minQty":10,"label":"10–24 packs","unitPriceNgn":2800,"unitPriceGbp":7},{"minQty":25,"label":"25–49 packs","unitPriceNgn":2500,"unitPriceGbp":6.25},{"minQty":50,"label":"50+ packs","unitPriceNgn":2200,"unitPriceGbp":5.5}]'::jsonb, 'Inquire for Timeline', 'asset:product-asoebi.jpg', '[{"src":"asset:detail-asoebi-macro.jpg","caption":"Asoebi print detail"},{"src":"asset:detail-asoebi-bulk.jpg","caption":"Bulk coordination selection"}]'::jsonb, true, 4)
) AS v(code, name, category, variant, description, pattern, option_label, options, min_qty, price_ngn, price_gbp, volume_tiers, stock_status, image_url, gallery, published, sort_order)
WHERE NOT EXISTS (SELECT 1 FROM public.products p WHERE p.code = v.code);